        spec,
        version: pickedPackage.version,
        defaultPinnedVersion: opts.pinnedVersion,
      })
      : undefined,
    resolution,
    resolvedVia: 'named-registry',
    registryName: spec.registryName,
    publishedAt: meta.time?.[pickedPackage.version],
    alias: spec.name,
  }
}

